import{_ as a,o as t,c as s,a6 as n}from"./chunks/framework.BHBQfcoO.js";const m=JSON.parse('{"title":"Getting AI Help Writing LCARdS Config","description":"","frontmatter":{},"headers":[],"relativePath":"cards/ai-assistance.md","filePath":"cards/ai-assistance.md"}'),o={name:"cards/ai-assistance.md"};function r(i,e,c,l,h,d){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="getting-ai-help-writing-lcards-config" tabindex="-1">Getting AI Help Writing LCARdS Config <a class="header-anchor" href="#getting-ai-help-writing-lcards-config" aria-label="Permalink to &quot;Getting AI Help Writing LCARdS Config&quot;">​</a></h1><p>You can use ChatGPT, Claude, or any other LLM to help write LCARdS YAML. Left to itself, though, an LLM has never seen LCARdS&#39;s actual config schema; it will happily invent plausible-looking properties that don&#39;t exist. Giving it the real schema up front fixes that.</p><h2 id="what-to-attach" tabindex="-1">What to attach <a class="header-anchor" href="#what-to-attach" aria-label="Permalink to &quot;What to attach&quot;">​</a></h2><p><strong>1. The schema for your card (required).</strong> LCARdS publishes the exact JSON Schemas it validates config against, generated straight from the source so they can&#39;t drift out of date. Pick one of:</p><ul><li><strong>One card at a time (smallest):</strong> the card&#39;s file from <a href="/schema/index.json"><code>schema/index.json</code></a>, e.g. <a href="/schema/cards/lcards-button.json"><code>schema/cards/lcards-button.json</code></a> or <a href="/schema/cards/lcards-msd-card.json"><code>schema/cards/lcards-msd-card.json</code></a>, plus the shared files its index entry lists under <code>uses</code> (rules, animations, background animations, state colours, filters). Card files are 2 to 75 KB; attach only the shared files your request touches.</li><li><strong>Everything in one file:</strong> <a href="/lcards-schema.json"><code>lcards-schema.json</code></a>: every card (<code>cards</code>, including MSD), the <a href="./layout-view/">Layout View</a> (<code>views</code>) and the LCARS shell dashboard strategy (<code>strategies</code>). About 460 KB, so it suits tools with large context windows.</li></ul><p>Each GitHub release also carries both as assets (<code>lcards-schema.json</code>, <code>lcards-schema.zip</code>), matching that release&#39;s options exactly.</p><p><strong>2. <a href="./common.html">Common Properties</a> (recommended)</strong>: covers things the raw schema&#39;s types don&#39;t fully explain in prose: entity reference patterns, the <code>theme:</code> prefix required for theme tokens, <code>{{ }}</code> template syntax, and action config.</p><p><strong>3. The specific card&#39;s reference page (optional)</strong>: e.g. <a href="./button/">Button</a>, <a href="./chart/">Chart</a>, for real worked YAML examples in context, not just a type list.</p><h2 id="prompt-template" tabindex="-1">Prompt template <a class="header-anchor" href="#prompt-template" aria-label="Permalink to &quot;Prompt template&quot;">​</a></h2><p>Paste this ahead of your actual request, with the schema file and doc pages attached:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I&#39;m writing YAML configuration for LCARdS, a custom Home Assistant Lovelace</span></span>
<span class="line"><span>card system. I&#39;ve attached its JSON Schema (from https://lcards.unimatrix01.ca/schema/index.json)</span></span>
<span class="line"><span>and reference docs. Rules:</span></span>
<span class="line"><span>- Only use properties that appear in the schema for the card type I&#39;m using</span></span>
<span class="line"><span>  (resolve &quot;#/$defs/...&quot; refs within the file, and &quot;../shared/&lt;name&gt;.json&quot; refs</span></span>
<span class="line"><span>  against the shared files I attached).</span></span>
<span class="line"><span>- Do not invent properties. If something I ask for isn&#39;t in the schema, tell</span></span>
<span class="line"><span>  me instead of guessing at a plausible-sounding key.</span></span>
<span class="line"><span>- Colour values must match the schema&#39;s colour pattern: hex, rgb()/rgba()/</span></span>
<span class="line"><span>  hsl()/hsla(), var(--name), or a theme:path token (e.g. theme:colors.ui.primary).</span></span></code></pre></div><p>Then describe the card you want.</p><h2 id="msd" tabindex="-1">MSD <a class="header-anchor" href="#msd" aria-label="Permalink to &quot;MSD&quot;">​</a></h2><p>The MSD schema (<code>custom:lcards-msd-card</code>) is large and deeply nested (routing, overlays, filters, animation triggers). Attach <a href="/schema/cards/lcards-msd-card.json"><code>schema/cards/lcards-msd-card.json</code></a> with the shared files it uses, plus the relevant page(s) from the <a href="./msd/">MSD docs</a> (start with <a href="./msd/quick-start.html">Quick Start</a> or <a href="./msd/routing-concepts.html">Routing Concepts</a>), and expect to iterate more than with a single button.</p><h2 id="if-it-still-invents-a-key" tabindex="-1">If it still invents a key <a class="header-anchor" href="#if-it-still-invents-a-key" aria-label="Permalink to &quot;If it still invents a key&quot;">​</a></h2><p>Paste the error (or the YAML that didn&#39;t work) back to the LLM along with a reminder to re-check the attached schema before answering; most models will correct themselves once told explicitly not to guess.</p>`,16)])])}const u=a(o,[["render",r]]);export{m as __pageData,u as default};
